import pandas as pd
import numpy as np

train = pd.read_csv('train.csv')
y = train['target'].values
X = train.drop(columns=['target']).values

X_train, X_val = X[:6000], X[6000:]
y_train, y_val = y[:6000], y[6000:]

class DecisionTreeRegressor:
    def __init__(self, max_depth=3):
        self.max_depth = max_depth

    def fit(self, X, y):
        self.tree = self._build_tree(X, y, 0)

    def _build_tree(self, X, y, depth):
        if depth == self.max_depth or len(np.unique(y)) == 1 or len(y) < 2:
            return np.mean(y)

        best_gain = -1
        best_f = None
        best_t = None

        # Subsample features for speed (like RF)
        features = np.random.choice(X.shape[1], int(np.sqrt(X.shape[1])), replace=False)

        for f in features:
            thresholds = np.percentile(X[:, f], [25, 50, 75])
            for t in thresholds:
                left_mask = X[:, f] <= t
                right_mask = ~left_mask
                if np.sum(left_mask) == 0 or np.sum(right_mask) == 0: continue

                var_total = np.var(y)
                var_left = np.var(y[left_mask])
                var_right = np.var(y[right_mask])

                n = len(y)
                gain = var_total - (np.sum(left_mask)/n * var_left + np.sum(right_mask)/n * var_right)

                if gain > best_gain:
                    best_gain = gain
                    best_f = f
                    best_t = t

        if best_gain <= 0:
            return np.mean(y)

        left_mask = X[:, best_f] <= best_t
        right_mask = ~left_mask

        return {
            'f': best_f,
            't': best_t,
            'left': self._build_tree(X[left_mask], y[left_mask], depth+1),
            'right': self._build_tree(X[right_mask], y[right_mask], depth+1)
        }

    def predict(self, X):
        return np.array([self._predict_one(x, self.tree) for x in X])

    def _predict_one(self, x, node):
        if not isinstance(node, dict):
            return node
        if x[node['f']] <= node['t']:
            return self._predict_one(x, node['left'])
        else:
            return self._predict_one(x, node['right'])

class GBM:
    def __init__(self, n_estimators=50, learning_rate=0.1, max_depth=3):
        self.n_estimators = n_estimators
        self.learning_rate = learning_rate
        self.max_depth = max_depth
        self.trees = []

    def fit(self, X, y):
        self.F = np.zeros(len(y))
        for i in range(self.n_estimators):
            p = 1 / (1 + np.exp(-self.F))
            residual = y - p

            tree = DecisionTreeRegressor(max_depth=self.max_depth)
            tree.fit(X, residual)
            pred = tree.predict(X)

            self.F += self.learning_rate * pred
            self.trees.append(tree)

            if i % 10 == 0:
                p_val = self.predict_proba(X_val)
                acc_val = np.mean((p_val > 0.5) == y_val)
                print(f"Tree {i}, Val Acc: {acc_val:.4f}")

    def predict_proba(self, X):
        F = np.zeros(len(X))
        for tree in self.trees:
            F += self.learning_rate * tree.predict(X)
        return 1 / (1 + np.exp(-F))

gbm = GBM(n_estimators=50, learning_rate=0.1, max_depth=3)
gbm.fit(X_train, y_train)
